# WoWClient.exe improvement patch for WoW 0.5.3 (see README.txt)
# Changes only the bytes listed below, and only in a known WoWClient.exe
# (checked with SHA256 before and after). A backup is kept.
# Usage: double-click patch.bat, or run:  powershell -ExecutionPolicy Bypass -File patch.ps1 [path\to\WoWClient.exe]

param([string]$Path = "")

$ErrorActionPreference = "Stop"
if ($Path -eq "") { $Path = Join-Path $PSScriptRoot "WoWClient.exe" }

function Get-Sha256([byte[]]$Data) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([System.BitConverter]::ToString($sha.ComputeHash($Data))).Replace("-", "") }
    finally { $sha.Dispose() }
}

function Convert-Hex([string]$Hex) {
    $bytes = New-Object byte[] ($Hex.Length / 2)
    for ($i = 0; $i -lt $bytes.Length; $i++) {
        $bytes[$i] = [System.Convert]::ToByte($Hex.Substring($i * 2, 2), 16)
    }
    return ,$bytes
}

